/**
 * Gentok dashboard translations.
 *
 * The interface is written in French. This script translates every visible text, placeholder
 * and tooltip into the selected language, including content added later by app.js
 * (lists, toasts, dialogs, server notifications) thanks to a MutationObserver.
 *
 * Dictionaries: public/i18n/<lang>.js (generated by scripts/i18n-build.py from
 * public/i18n/source.json + public/i18n/<lang>.json). A missing text simply stays in French.
 *
 * This file must be loaded in <head>, before the page scripts.
 */
(function () {
    const LANGUAGES = {
        fr: { name: 'Français', flag: '🇫🇷' },
        en: { name: 'English', flag: '🇬🇧' },
        es: { name: 'Español', flag: '🇪🇸' },
        de: { name: 'Deutsch', flag: '🇩🇪' },
        pt: { name: 'Português', flag: '🇧🇷' },
        it: { name: 'Italiano', flag: '🇮🇹' }
    };
    const STORAGE_KEY = 'gentok_lang';

    function readSaved() {
        try { return localStorage.getItem(STORAGE_KEY); } catch (e) { return null; }
    }
    const saved = readSaved();
    const browser = (navigator.language || 'fr').slice(0, 2).toLowerCase();
    const lang = LANGUAGES[saved] ? saved : (LANGUAGES[browser] ? browser : 'fr');
    document.documentElement.lang = lang;

    const exact = new Map();
    const patterns = [];
    const norm = (s) => String(s).replace(/\s+/g, ' ').trim();
    const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

    // Called by public/i18n/<lang>.js
    window.__gentokRegisterDictionary = function (dict) {
        for (const [src, dst] of Object.entries(dict.texts || {})) {
            if (dst) exact.set(norm(src), dst);
        }
        for (const [src, dst] of Object.entries(dict.patterns || {})) {
            if (!dst) continue;
            const re = new RegExp('^' + escapeRe(norm(src)).replace(/\\\{(\d+)\\\}/g, '(.+?)') + '$');
            const order = [...src.matchAll(/\{(\d+)\}/g)].map(m => Number(m[1]));
            patterns.push({ re, dst, order });
        }
    };

    if (lang !== 'fr') {
        // Parser-blocking load so that the dictionary is ready before the page renders
        document.write(`<script src="/i18n/${lang}.js"><\/script>`);
    }

    /** Translates one French string, or returns null if unknown */
    function lookup(text) {
        const key = norm(text);
        if (!key) return null;
        if (exact.has(key)) return exact.get(key);
        for (const p of patterns) {
            const m = key.match(p.re);
            if (m) {
                let out = p.dst;
                p.order.forEach((n, i) => { out = out.split(`{${n}}`).join(m[i + 1]); });
                return out;
            }
        }
        return null;
    }

    function t(text) {
        if (lang === 'fr' || text === null || text === undefined) return text;
        const tr = lookup(text);
        return tr === null ? text : tr;
    }

    const SKIP_TAGS = new Set(['SCRIPT', 'STYLE', 'TEXTAREA', 'CODE', 'PRE', 'NOSCRIPT']);
    const ATTRS = ['placeholder', 'title', 'aria-label', 'alt', 'data-tooltip'];

    function translateTextNode(node) {
        const parent = node.parentElement;
        if (!parent || SKIP_TAGS.has(parent.tagName) || parent.closest('[data-no-i18n]')) return;
        const value = node.nodeValue;
        if (!value || !/[A-Za-zÀ-ÿ]/.test(value)) return;
        const tr = lookup(value);
        if (tr !== null && tr !== norm(value)) {
            const lead = value.match(/^\s*/)[0];
            const trail = value.match(/\s*$/)[0];
            node.nodeValue = lead + tr + trail;
        }
    }

    function translateAttributes(el) {
        if (el.closest && el.closest('[data-no-i18n]')) return;
        for (const attr of ATTRS) {
            const v = el.getAttribute && el.getAttribute(attr);
            if (v) {
                const tr = lookup(v);
                if (tr !== null && tr !== v) el.setAttribute(attr, tr);
            }
        }
        if (el.tagName === 'INPUT' && (el.type === 'button' || el.type === 'submit') && el.value) {
            const tr = lookup(el.value);
            if (tr !== null) el.value = tr;
        }
    }

    function translateTree(root) {
        if (lang === 'fr' || !root) return;
        if (root.nodeType === Node.TEXT_NODE) return translateTextNode(root);
        if (root.nodeType !== Node.ELEMENT_NODE && root.nodeType !== Node.DOCUMENT_NODE) return;
        if (root.nodeType === Node.ELEMENT_NODE) {
            if (SKIP_TAGS.has(root.tagName)) return;
            translateAttributes(root);
        }
        const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT);
        let n;
        while ((n = walker.nextNode())) {
            if (n.nodeType === Node.TEXT_NODE) translateTextNode(n);
            else translateAttributes(n);
        }
    }

    function start() {
        if (lang === 'fr') return;
        translateTree(document.body);
        document.title = t(document.title);
        const observer = new MutationObserver((mutations) => {
            for (const m of mutations) {
                if (m.type === 'childList') m.addedNodes.forEach(translateTree);
                else if (m.type === 'characterData') translateTextNode(m.target);
                else if (m.type === 'attributes') translateAttributes(m.target);
            }
        });
        observer.observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ATTRS });
    }

    if (lang !== 'fr') {
        // Native dialogs
        const nativeAlert = window.alert.bind(window);
        const nativeConfirm = window.confirm.bind(window);
        const nativePrompt = window.prompt.bind(window);
        window.alert = (msg) => nativeAlert(t(msg));
        window.confirm = (msg) => nativeConfirm(t(msg));
        window.prompt = (msg, def) => nativePrompt(t(msg), def);
    }

    function setLanguage(code, { save = true, reload = true } = {}) {
        if (!LANGUAGES[code]) return;
        try { localStorage.setItem(STORAGE_KEY, code); } catch (e) { }
        if (save) {
            try {
                const token = localStorage.getItem('gentok_token');
                const base = typeof window.getApiBase === 'function' ? window.getApiBase() : '';
                if (token) {
                    fetch(`${base}/api/settings`, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ token, language: code })
                    }).catch(() => { });
                }
            } catch (e) { }
        }
        if (reload && code !== lang) setTimeout(() => window.location.reload(), 150);
    }

    /** Fills every <select data-language-select> with the available languages */
    function initSelectors() {
        document.querySelectorAll('select[data-language-select]').forEach(sel => {
            sel.setAttribute('data-no-i18n', '');
            sel.innerHTML = Object.entries(LANGUAGES)
                .map(([code, l]) => `<option value="${code}"${code === lang ? ' selected' : ''}>${l.flag} ${l.name}</option>`)
                .join('');
            sel.addEventListener('change', () => setLanguage(sel.value));
        });
    }

    window.GentokI18n = { lang, languages: LANGUAGES, t, setLanguage, translate: translateTree };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => { initSelectors(); start(); });
    } else {
        initSelectors();
        start();
    }
})();
